  { json: { browseNodeId: '7791985011', categoryName: 'celulares' } }
];

// Gera assinatura AWS4 para a PA-API
// Credenciais via variáveis de ambiente do n8n
const crypto = require('crypto');

const accessKey = $env.AMAZON_ACCESS_KEY;
const secretKey = $env.AMAZON_SECRET_KEY;
const partnerTag = $env.AMAZON_PARTNER_TAG;
const host = 'webservices.amazon.com.br';
const region = 'us-east-1';
const service = 'ProductAdvertisingAPI';
const operation = 'SearchItems';

const items = [];

for (const item of $input.all()) {
  const { browseNodeId, categoryName } = item.json;

  const payload = JSON.stringify({
    Keywords: 'tech',
    Resources: [
      'Offers.Listings.Price',
      'Offers.Listings.SavingBasis',
      'CustomerReviews.StarRating',
      'CustomerReviews.Count',
      'Images.Primary.Large',
      'ItemInfo.Title',
      'ItemInfo.ByLineInfo'
    ],
    SearchIndex: 'Electronics',
    BrowseNodeId: browseNodeId,
    MinSavingPercent: 15,
    PartnerTag: partnerTag,
    PartnerType: 'Associates',
    Marketplace: 'www.amazon.com.br'
  });

  // Cabeçalhos necessários
  const now = new Date();
  const amzDate = now.toISOString().replace(/[:\-]|\.\d{3}/g, '').slice(0, 15) + 'Z';
  const dateStamp = amzDate.slice(0, 8);

  const canonicalHeaders = `content-encoding:amz-1.0\ncontent-type:application/json; charset=utf-8\nhost:${host}\nx-amz-date:${amzDate}\nx-amz-target:com.amazon.paapi5.v1.ProductAdvertisingAPIv1.${operation}\n`;
  const signedHeaders = 'content-encoding;content-type;host;x-amz-date;x-amz-target';
  const payloadHash = crypto.createHash('sha256').update(payload).digest('hex');

  const canonicalRequest = `POST\n/paapi5/searchitems\n\n${canonicalHeaders}\n${signedHeaders}\n${payloadHash}`;
  const credentialScope = `${dateStamp}/${region}/${service}/aws4_request`;
  const stringToSign = `AWS4-HMAC-SHA256\n${amzDate}\n${credentialScope}\n${crypto.createHash('sha256').update(canonicalRequest).digest('hex')}`;

  const hmac = (key, data) => crypto.createHmac('sha256', key).update(data).digest();
  const signingKey = hmac(hmac(hmac(hmac(`AWS4${secretKey}`, dateStamp), region), service), 'aws4_request');
  const signature = crypto.createHmac('sha256', signingKey).update(stringToSign).digest('hex');

  const authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  items.push({
    json: {
      categoryName,
      browseNodeId,
      payload,
      headers: {
        'Content-Encoding': 'amz-1.0',
        'Content-Type': 'application/json; charset=utf-8',
        'Host': host,
        'X-Amz-Date': amzDate,
        'X-Amz-Target': `com.amazon.paapi5.v1.ProductAdvertisingAPIv1.${operation}`,
        'Authorization': authorization
      }
    }
  });
}

return items;

const crypto = require('crypto');
const partnerTag = $env.AMAZON_PARTNER_TAG;
const items = [];

for (const item of $input.all()) {
  const results = item.json.SearchResult?.Items || [];

  for (const product of results) {
    const title = product.ItemInfo?.Title?.DisplayValue || '';
    const brand = product.ItemInfo?.ByLineInfo?.Brand?.DisplayValue || null;
    const asin = product.ASIN || '';
    const urlOriginal = `https://www.amazon.com.br/dp/${asin}?tag=${partnerTag}`;
    const imageUrl = product.Images?.Primary?.Large?.URL || null;

    const listing = product.Offers?.Listings?.[0];
    if (!listing) continue;

    const priceCurrent = listing.Price?.Amount || 0;
    const priceOriginal = listing.SavingBasis?.Amount || null;
    const discountPct = priceOriginal && priceCurrent
      ? Math.round(((priceOriginal - priceCurrent) / priceOriginal) * 100)
      : null;

    const rating = product.CustomerReviews?.StarRating?.Value || null;
    const reviewsCount = product.CustomerReviews?.Count || null;

    if (priceCurrent <= 0) continue;

    const hashInput = (urlOriginal + asin).toLowerCase().trim();
    const hashDedup = crypto.createHash('sha256').update(hashInput).digest('hex');

    items.push({
      json: {
        source: 'amazon',
        external_id: asin,
        hash_dedup: hashDedup,
        title: title.slice(0, 500),
        url_original: urlOriginal,
        store: 'amazon',
        brand,
        price_current: priceCurrent,
        price_original: priceOriginal,
        discount_pct: discountPct,
        rating,
        reviews_count: reviewsCount,
        image_url: imageUrl,
        raw_payload: product,
      }
    });
  }
}

return items;
